struct GuardedBox {
    value: i32,
}

impl Drop for GuardedBox {
    fn drop(&mut self) {
        println!("GuardedBox dropped with value: {}", self.value);
    }
}

fn main() {
    let mut guarded = GuardedBox { value: 42 };
    let owned_box: Box<GuardedBox> = Box::new(GuardedBox { value: 100 });
    let owned_box2: Box<GuardedBox> = Box::new(GuardedBox { value: 200 });
    let owned_box3: Box<GuardedBox> = Box::new(GuardedBox { value: 300 });
    let owned_box4: Box<GuardedBox> = Box::new(GuardedBox { value: 400 });
    let owned_box5: Box<GuardedBox> = Box::new(GuardedBox { value: 500 });
    let owned_box6: Box<GuardedBox> = Box::new(GuardedBox { value: 600 });
    let owned_box7: Box<GuardedBox> = Box::new(GuardedBox { value: 700 });
    let owned_box8: Box<GuardedBox> = Box::new(GuardedBox { value: 800 });
    let owned_box9: Box<GuardedBox> = Box::new(GuardedBox { value: 900 });
    let owned_box10: Box<GuardedBox> = Box::new(GuardedBox { value: 1000 });

    assert_eq!(guarded.value, 42);
    assert_eq!(owned_box.value, 100);
    assert_eq!(owned_box2.value, 200);
    assert_eq!(owned_box3.value, 300);
    assert_eq!(owned_box4.value, 400);
    assert_eq!(owned_box5.value, 500);
    assert_eq!(owned_box6.value, 600);
    assert_eq!(owned_box7.value, 700);
    assert_eq!(owned_box8.value, 800);
    assert_eq!(owned_box9.value, 900);
    assert_eq!(owned_box10.value, 1000);

    drop(guarded);
    drop(owned_box);
    drop(owned_box2);
    drop(owned_box3);
    drop(owned_box4);
    drop(owned_box5);
    drop(owned_box6);
    drop(owned_box7);
    drop(owned_box8);
    drop(owned_box9);
    drop(owned_box10);

    println!("Ownership test passed");
}
